// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./interfaces/IZKVerify.sol";

/**
 * @title SP1Verifier
 * @dev Verifies SP1 zk proofs for carbon index calculations
 * This contract verifies that carbon index calculations were performed correctly
 * without revealing the underlying data or computation details.
 */
contract SP1Verifier is Ownable, ReentrancyGuard {

    // ZKVerify contract for proof verification
    IZKVerify public immutable zkVerify;

    // Struct to hold the public values from the SP1 proof
    struct CarbonIndexProof {
        uint256 nhiScore;           // Natural Hazard Index score (scaled by 1e18)
        uint256 p20Percentile;      // 20th percentile (scaled by 1e18)
        uint256 p90Percentile;      // 90th percentile (scaled by 1e18)
        uint256 gammaShape;         // Gamma distribution shape parameter (scaled by 1e18)
        uint256 gammaScale;         // Gamma distribution scale parameter (scaled by 1e18)
        uint256 gammaLoc;           // Gamma distribution location parameter (scaled by 1e18)
        uint256 carbonIndexValue;   // Final carbon index value (scaled by 1e18)
        uint256 timestamp;          // Timestamp of the calculation
        uint256 latMin;             // Minimum latitude (scaled by 1e18)
        uint256 latMax;             // Maximum latitude (scaled by 1e18)
        uint256 lonMin;             // Minimum longitude (scaled by 1e18)
        uint256 lonMax;             // Maximum longitude (scaled by 1e18)
    }

    // SP1 proof verification key (this would be generated from the SP1 program)
    bytes32 public constant VERIFICATION_KEY = keccak256("SP1_CARBON_INDEX_VERIFICATION_KEY");

    // Mapping to store verified proofs
    mapping(bytes32 => bool) public verifiedProofs;

    // Mapping to store proof metadata
    mapping(bytes32 => CarbonIndexProof) public proofData;

    // Mapping to store ZKVerify proof IDs by proof hash
    mapping(bytes32 => bytes32) public proofIdByHash;

    // Mapping to store proof submission status
    mapping(bytes32 => bool) public proofSubmitted;

    // Events
    event ProofVerified(
        bytes32 indexed proofHash,
        uint256 carbonIndexValue,
        uint256 timestamp,
        address indexed verifier
    );

    event ProofRejected(
        bytes32 indexed proofHash,
        string reason
    );

    event ProofSubmittedToZKVerify(
        bytes32 indexed proofHash,
        bytes32 indexed zkVerifyProofId
    );

    // Constructor
    constructor(address _zkVerify) {
        require(_zkVerify != address(0), "Invalid ZKVerify address");
        zkVerify = IZKVerify(_zkVerify);
    }

    // Modifiers
    modifier onlyValidProof(bytes32 proofHash) {
        require(!verifiedProofs[proofHash], "Proof already verified");
        _;
    }

    /**
     * @dev Verify an SP1 proof for carbon index calculation
     * @param proof The SP1 proof bytes
     * @param publicValues The public values from the proof
     * @param proofHash Hash of the proof for deduplication
     */
    function verifyProof(
        bytes calldata proof,
        CarbonIndexProof calldata publicValues,
        bytes32 proofHash
    ) external onlyValidProof(proofHash) nonReentrant {
        // Validate input parameters
        require(proof.length > 0, "Invalid proof");
        require(publicValues.timestamp > 0, "Invalid timestamp");
        require(publicValues.latMin < publicValues.latMax, "Invalid latitude range");
        require(publicValues.lonMin < publicValues.lonMax, "Invalid longitude range");
        require(publicValues.carbonIndexValue <= 1e18, "Invalid carbon index value");

        // Submit proof to ZKVerify for verification
        bool submitted = _submitToZKVerify(proof, publicValues, proofHash);

        if (submitted) {
            // Store the proof data (not yet verified)
            proofData[proofHash] = publicValues;
            proofSubmitted[proofHash] = true;

            emit ProofSubmittedToZKVerify(proofHash, proofIdByHash[proofHash]);
        } else {
            emit ProofRejected(proofHash, "Failed to submit proof to ZKVerify");
            revert("Proof submission failed");
        }
    }

    /**
     * @dev Submit proof to ZKVerify for verification
     * @param proof The proof bytes
     * @param publicValues The public values
     * @param proofHash The proof hash
     * @return submitted Whether the proof was successfully submitted
     */
    function _submitToZKVerify(
        bytes calldata proof,
        CarbonIndexProof calldata publicValues,
        bytes32 proofHash
    ) internal returns (bool) {
        try zkVerify.submitProof(
            proof,
            _encodePublicValues(publicValues)
        ) returns (bytes32 zkVerifyProofId) {
            proofIdByHash[proofHash] = zkVerifyProofId;
            return true;
        } catch {
            return false;
        }
    }

    /**
     * @dev Encode public values into bytes for ZKVerify
     * @param publicValues The public values struct
     * @return encoded The encoded bytes
     */
    function _encodePublicValues(CarbonIndexProof calldata publicValues) internal pure returns (bytes memory) {
        return abi.encode(
            publicValues.nhiScore,
            publicValues.p20Percentile,
            publicValues.p90Percentile,
            publicValues.gammaShape,
            publicValues.gammaScale,
            publicValues.gammaLoc,
            publicValues.carbonIndexValue,
            publicValues.timestamp,
            publicValues.latMin,
            publicValues.latMax,
            publicValues.lonMin,
            publicValues.lonMax
        );
    }

    /**
     * @dev Finalize proof verification after ZKVerify has processed it
     * @param proofHash The proof hash to finalize
     */
    function finalizeProof(bytes32 proofHash) external nonReentrant {
        require(proofSubmitted[proofHash], "Proof not submitted");
        require(!verifiedProofs[proofHash], "Proof already verified");

        bytes32 zkVerifyProofId = proofIdByHash[proofHash];
        require(zkVerifyProofId != bytes32(0), "Invalid ZKVerify proof ID");

        try zkVerify.verifyProof(zkVerifyProofId) returns (bool verified) {
            if (verified) {
                verifiedProofs[proofHash] = true;
                CarbonIndexProof memory proofData_ = proofData[proofHash];

                emit ProofVerified(
                    proofHash,
                    proofData_.carbonIndexValue,
                    proofData_.timestamp,
                    msg.sender
                );
            } else {
                emit ProofRejected(proofHash, "ZKVerify verification failed");
                revert("Proof verification failed");
            }
        } catch {
            emit ProofRejected(proofHash, "ZKVerify verification error");
            revert("Proof verification error");
        }
    }

    /**
     * @dev Check if a proof has been verified
     * @param proofHash Hash of the proof
     * @return isVerified Whether the proof is verified
     */
    function isProofVerified(bytes32 proofHash) external view returns (bool) {
        return verifiedProofs[proofHash];
    }

    /**
     * @dev Check if a proof has been submitted to ZKVerify
     * @param proofHash Hash of the proof
     * @return isSubmitted Whether the proof has been submitted
     */
    function isProofSubmitted(bytes32 proofHash) external view returns (bool) {
        return proofSubmitted[proofHash];
    }

    /**
     * @dev Get ZKVerify proof ID for a given proof hash
     * @param proofHash Hash of the proof
     * @return zkVerifyProofId The ZKVerify proof ID
     */
    function getZKVerifyProofId(bytes32 proofHash) external view returns (bytes32) {
        return proofIdByHash[proofHash];
    }

    /**
     * @dev Get proof data for a verified proof
     * @param proofHash Hash of the proof
     * @return proof The proof data
     */
    function getProofData(bytes32 proofHash) external view returns (CarbonIndexProof memory) {
        require(verifiedProofs[proofHash], "Proof not verified");
        return proofData[proofHash];
    }

    /**
     * @dev Get the carbon index value from a verified proof
     * @param proofHash Hash of the proof
     * @return carbonIndexValue The carbon index value
     */
    function getCarbonIndexValue(bytes32 proofHash) external view returns (uint256) {
        require(verifiedProofs[proofHash], "Proof not verified");
        return proofData[proofHash].carbonIndexValue;
    }

    /**
     * @dev Emergency function to revoke a proof (only owner)
     * @param proofHash Hash of the proof to revoke
     */
    function revokeProof(bytes32 proofHash) external onlyOwner {
        require(verifiedProofs[proofHash], "Proof not verified");
        delete verifiedProofs[proofHash];
        delete proofData[proofHash];
    }

    /**
     * @dev Update verification key (only owner)
     * @param newVerificationKey New verification key
     */
    function updateVerificationKey(bytes32 newVerificationKey) external onlyOwner {
        // In practice, this would update the actual verification key
        // For now, we'll just emit an event
        emit ProofVerified(bytes32(0), 0, block.timestamp, msg.sender);
    }
}

contracts/UMAInputOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @dev UMA OOV3 minimal interface (top-level)
 */
interface OptimisticOracleV3Interface {
    function defaultIdentifier() external view returns (bytes32);

    function assertTruth(
        bytes memory claim,
        address asserter,
        address callbackRecipient,
        address escalationManager,
        uint64 liveness,
        IERC20 currency,
        uint256 bond,
        bytes32 identifier,
        bytes32 domain
    ) external returns (bytes32 assertionId);

    function settleAssertion(bytes32 assertionId) external returns (bool assertedTruthfully);
}

/**
 * @title UMA Optimistic Oracle V3 Data-Asserter-style Input Oracle
 * @notice Integrates UMA OOV3 to assert and settle arbitrary off-chain data on-chain.
 *         Mirrors the Data Asserter tutorial flow from UMA docs, adapted to expose
 *         latest(dataId) reads for downstream contracts.
 *
 * References:
 * - UMA OOV3 Data Asserter: https://docs.uma.xyz/developers/optimistic-oracle-v3/data-asserter
 */
contract UMAInputOracle is Ownable {
    // ----------------------------
    // Storage
    // ----------------------------
    IERC20 public defaultCurrency;                // Bond currency
    OptimisticOracleV3Interface public oo;        // UMA OOV3 instance
    bytes32 public defaultIdentifier;             // Price identifier used for assertions

    // Global parameters (can be tuned by owner)
    uint64 public assertionLiveness;              // Challenge window in seconds
    uint256 public bond;                          // Bond amount in `defaultCurrency`
    bytes32 public domain;                        // Optional domain separation for claims

    // Data assertion object as in UMA example
    struct DataAssertion {
        bytes32 dataId;        // Unique identifier of the data
        bytes32 data;          // Bytes32-encoded value asserted
        address asserter;      // Address credited at resolution
        bool resolved;         // Whether settled
        bool truthfully;       // Whether resolved as truthful
    }

    // assertionId => DataAssertion
    mapping(bytes32 => DataAssertion) public assertionsData;

    // dataId => latest assertionId
    mapping(bytes32 => bytes32) public latestAssertionByDataId;

    // Optionally track last resolved value per dataId for quick reads
    mapping(bytes32 => bytes32) public resolvedDataById;

    // ----------------------------
    // Events
    // ----------------------------
    event AssertionCreated(
        bytes32 indexed dataId,
        bytes32 indexed assertionId,
        address indexed asserter,
        bytes32 data,
        uint64 liveness,
        uint256 bond
    );

    event AssertionResolved(
        bytes32 indexed dataId,
        bytes32 indexed assertionId,
        bool assertedTruthfully,
        bytes32 data
    );

    event ConfigUpdated(
        address defaultCurrency,
        address oo,
        uint64 assertionLiveness,
        uint256 bond,
        bytes32 defaultIdentifier,
        bytes32 domain
    );

    // ----------------------------
    // Constructor
    // ----------------------------
    constructor(address _defaultCurrency, address _optimisticOracleV3) {
        require(_defaultCurrency != address(0), "invalid currency");
        require(_optimisticOracleV3 != address(0), "invalid oracle");

        defaultCurrency = IERC20(_defaultCurrency);
        oo = OptimisticOracleV3Interface(_optimisticOracleV3);
        defaultIdentifier = oo.defaultIdentifier();

        // Sensible defaults (owner can update later)
        assertionLiveness = 2 hours;
        bond = 0; // In many tutorial/test environments default bond may be 0
        domain = bytes32(0);

        emit ConfigUpdated(_defaultCurrency, _optimisticOracleV3, assertionLiveness, bond, defaultIdentifier, domain);
    }

    // ----------------------------
    // Admin configuration
    // ----------------------------
    function setAssertionLiveness(uint64 newLiveness) external onlyOwner {
        assertionLiveness = newLiveness;
        emit ConfigUpdated(address(defaultCurrency), address(oo), assertionLiveness, bond, defaultIdentifier, domain);
    }

    function setBond(uint256 newBond) external onlyOwner {
        bond = newBond;
        emit ConfigUpdated(address(defaultCurrency), address(oo), assertionLiveness, bond, defaultIdentifier, domain);
    }

    function setDomain(bytes32 newDomain) external onlyOwner {
        domain = newDomain;
        emit ConfigUpdated(address(defaultCurrency), address(oo), assertionLiveness, bond, defaultIdentifier, domain);
    }

    function setDefaultCurrency(address newCurrency) external onlyOwner {
        require(newCurrency != address(0), "invalid currency");
        defaultCurrency = IERC20(newCurrency);
        emit ConfigUpdated(address(defaultCurrency), address(oo), assertionLiveness, bond, defaultIdentifier, domain);
    }

    function setOracle(address newOO) external onlyOwner {
        require(newOO != address(0), "invalid oracle");
        oo = OptimisticOracleV3Interface(newOO);
        defaultIdentifier = oo.defaultIdentifier();
        emit ConfigUpdated(address(defaultCurrency), address(oo), assertionLiveness, bond, defaultIdentifier, domain);
    }

    // ----------------------------
    // Assertion flow (Data Asserter pattern)
    // ----------------------------

    /**
     * @notice Assert that `data` is the correct value for `dataId`.
     *         Pulls `bond` from caller, approves OO, and calls assertTruth.
     * @dev Callers must have approved this contract to transfer `bond` amount if bond>0.
     */
    function assertDataFor(bytes32 dataId, bytes32 data, address asserter) external returns (bytes32 assertionId) {
        // Pull bond into this contract then approve OO (if bond > 0)
        if (bond > 0) {
            require(defaultCurrency.transferFrom(msg.sender, address(this), bond), "bond transfer failed");
            require(defaultCurrency.approve(address(oo), bond), "approve failed");
        }

        // Build human-readable claim bytes as in UMA example (not used on-chain beyond dispute text)
        bytes memory claim = abi.encodePacked(
            "Data asserted: 0x",
            _toHex(data),
            " for dataId: 0x",
            _toHex(dataId),
            " and asserter: 0x",
            _toHexAddress(asserter),
            " at timestamp: ",
            _uintToUtf8(block.timestamp),
            " in UMAInputOracle at 0x",
            _toHexAddress(address(this)),
            " is valid."
        );

        assertionId = oo.assertTruth(
            claim,
            asserter,
            address(this),          // callback recipient
            address(0),             // no escalation manager
            assertionLiveness,
            defaultCurrency,
            bond,
            defaultIdentifier,
            domain
        );

        assertionsData[assertionId] = DataAssertion({
            dataId: dataId,
            data: data,
            asserter: asserter,
            resolved: false,
            truthfully: false
        });

        latestAssertionByDataId[dataId] = assertionId;

        emit AssertionCreated(dataId, assertionId, asserter, data, assertionLiveness, bond);
    }

    /**
     * @notice Convenience: settle an assertion after liveness window passes.
     *         Anyone can call; OO enforces liveness.
     */
    function settle(bytes32 assertionId) external returns (bool assertedTruthfully) {
        assertedTruthfully = oo.settleAssertion(assertionId);
        // The resolution callback below finalizes storage updates
    }

    // ----------------------------
    // UMA OOV3 Callbacks
    // ----------------------------

    /**
     * @notice Called by OOV3 on assertion settlement.
     */
    function assertionResolvedCallback(bytes32 assertionId, bool assertedTruthfully) external {
        require(msg.sender == address(oo), "only OO");
        DataAssertion storage da = assertionsData[assertionId];
        // Ignore unknown assertion IDs to avoid reverting OO
        if (da.asserter == address(0)) return;

        da.resolved = true;
        da.truthfully = assertedTruthfully;

        if (assertedTruthfully) {
            resolvedDataById[da.dataId] = da.data;
        }

        emit AssertionResolved(da.dataId, assertionId, assertedTruthfully, da.data);
    }

    /**
     * @notice Optional: called by OOV3 when an assertion is disputed.
     *         No-op here, but provided for completeness.
     */
    function assertionDisputedCallback(bytes32 /*assertionId*/) external view {
        require(msg.sender == address(oo), "only OO");
    }

    // ----------------------------
    // Read APIs
    // ----------------------------

    /**
     * @notice Returns latest assertion info for a given dataId.
     */
    function latest(bytes32 dataId) external view returns (
        bool isResolved,
        bool truthfully,
        bytes32 data,
        bytes32 assertionId
    ) {
        assertionId = latestAssertionByDataId[dataId];
        DataAssertion memory da = assertionsData[assertionId];
        return (da.resolved, da.truthfully, da.data, assertionId);
    }

    /**
     * @notice Return resolved data (if any) for a dataId. Zero if none or not truthful.
     */
    function latestResolved(bytes32 dataId) external view returns (bytes32) {
        return resolvedDataById[dataId];
    }

    // ----------------------------
    // Helpers (string/bytes formatting)
    // ----------------------------

    function _toHex(bytes32 data) internal pure returns (bytes memory) {
        bytes16 hexSymbols = 0x30313233343536373839616263646566; // 0-9a-f
        bytes memory str = new bytes(64);
        for (uint256 i = 0; i < 32; i++) {
            uint8 b = uint8(data[i]);
            str[2 * i] = bytes1(hexSymbols[b >> 4]);
            str[2 * i + 1] = bytes1(hexSymbols[b & 0x0f]);
        }
        return str;
    }

    function _toHexAddress(address account) internal pure returns (bytes memory) {
        return _toHex(bytes32(uint256(uint160(account))));
    }

    function _uintToUtf8(uint256 v) internal pure returns (bytes memory) {
        if (v == 0) return "0";
        uint256 j = v;
        uint256 len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory bstr = new bytes(len);
        uint256 k = len;
        j = v;
        while (j != 0) {
            k = k - 1;
            uint8 temp = uint8(48 + (j % 10));
            bstr[k] = bytes1(temp);
            j /= 10;
        }
        return bstr;
    }
}

contracts/VaultFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "./ProjectVault.sol";

/**
 * @title VaultFactory
 * @dev Deploys ERC-4626 ProjectVault instances per project/geography.
 */
contract VaultFactory is Ownable {
    event VaultDeployed(address indexed vault, address indexed asset, bytes32 indexed projectId, address indexSource, address owner);

    function deployVault(
        address asset,
        string memory vaultName,
        string memory vaultSymbol,
        bytes32 projectId,
        address indexSource,
        address owner_
    ) external onlyOwner returns (address) {
        require(asset != address(0), "invalid asset");
        ERC20 underlying = ERC20(asset);
        ProjectVault vault = new ProjectVault(
            underlying,
            vaultName,
            vaultSymbol,
            projectId,
            indexSource,
            owner_
        );
        emit VaultDeployed(address(vault), asset, projectId, indexSource, owner_);
        return address(vault);
    }
}

